import { useMemo, useState } from 'react';
import {
  Chip,
  ChipGroup,
  Card,
  CardBody,
  Stack,
  Inline,
  Text,
  Badge,
  CircularProgress,
  Pagination,
  EmptyState,
  Button,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'exceeded' | 'completed';

interface ProjectSpend {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'Приостановлен',
  exceeded: 'Превышена квота',
  completed: 'Завершён',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'neutral' | 'danger' | 'info'> = {
  active: 'success',
  paused: 'neutral',
  exceeded: 'danger',
  completed: 'info',
};

const PROJECTS: ProjectSpend[] = [
  { id: 'p1', name: 'Атлас маркетинга', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Обновление CRM', quotaPercent: 88, status: 'active' },
  { id: 'p3', name: 'Миграция данных', quotaPercent: 100, status: 'exceeded' },
  { id: 'p4', name: 'Портал поддержки', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Аналитика продаж', quotaPercent: 67, status: 'active' },
  { id: 'p6', name: 'Редизайн сайта', quotaPercent: 100, status: 'completed' },
  { id: 'p7', name: 'Мобильное приложение', quotaPercent: 93, status: 'exceeded' },
  { id: 'p8', name: 'Интеграция платежей', quotaPercent: 30, status: 'paused' },
  { id: 'p9', name: 'Внутренний портал', quotaPercent: 55, status: 'active' },
  { id: 'p10', name: 'Архив документов', quotaPercent: 100, status: 'completed' },
  { id: 'p11', name: 'Тестовый стенд', quotaPercent: 20, status: 'paused' },
  { id: 'p12', name: 'Обучающая платформа', quotaPercent: 76, status: 'active' },
];

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'exceeded', 'completed'];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([...STATUS_ORDER]);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);

  const pageProjects = useMemo(() => {
    const start = (safePage - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, safePage]);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([...STATUS_ORDER]);
    setPage(1);
  };

  return (
    <Card className="jx-w-full">
      <CardBody>
        <Stack gap="lg">
          <Stack gap="sm">
            <Text as="h2" variant="heading-sm">
              Расход по проектам
            </Text>
            <ChipGroup aria-label="Фильтр по статусу">
              {STATUS_ORDER.map((status) => {
                const selected = activeStatuses.includes(status);
                return (
                  <Chip
                    key={status}
                    selected={selected}
                    removable={selected}
                    onRemove={selected ? () => toggleStatus(status) : undefined}
                    onClick={() => toggleStatus(status)}
                    tone={STATUS_TONES[status]}
                  >
                    {STATUS_LABELS[status]}
                  </Chip>
                );
              })}
            </ChipGroup>
          </Stack>

          {filteredProjects.length === 0 ? (
            <EmptyState
              title="Нет проектов по выбранным фильтрам"
              description="Попробуйте изменить набор статусов или сбросьте фильтры."
              action={
                <Button variant="secondary" onClick={resetFilters}>
                  Сбросить фильтры
                </Button>
              }
            />
          ) : (
            <>
              <Stack gap="sm">
                {pageProjects.map((project) => (
                  <Inline
                    key={project.id}
                    align="center"
                    justify="between"
                    className="jx-p-3 jx-border jx-border-color-[var(--jx-color-border-default)] jx-rounded-md"
                  >
                    <Text variant="body-md">{project.name}</Text>
                    <Inline align="center" gap="md">
                      <CircularProgress
                        value={project.quotaPercent}
                        max={100}
                        size="sm"
                        label={`${project.quotaPercent}%`}
                        tone={STATUS_TONES[project.status]}
                      />
                      <Badge tone={STATUS_TONES[project.status]}>
                        {STATUS_LABELS[project.status]}
                      </Badge>
                    </Inline>
                  </Inline>
                ))}
              </Stack>

              <Pagination
                page={safePage}
                pageCount={totalPages}
                onPageChange={setPage}
                aria-label="Страницы проектов"
              />
            </>
          )}
        </Stack>
      </CardBody>
    </Card>
  );
}

